    Major_Moor_RidingStables: { name: '骑术马厩', description: '在每个剩余回合格上放置1 <FOOD>。\n在这些回合开始时，如果你拥有至少2<HORSE>，领取该<FOOD>。' },
    Major_Moor_MuseumOfTheMoors: { name: '沼泽博物馆', description: '以下大改良的成本减少1个对应建筑资源：\n水井 1 <STONE>      黏土烤炉 1 <CLAY>\n木工坊 1 <WOOD>      石制烤炉 1 <STONE>\n陶工坊 1 <CLAY>      护林人小屋 1 <CLAY>\n篮子编织坊 1 <REED>' },
    Major_Moor_HeatingOven: { name: '供暖炉', description: '立即获得2<FUEL>。\n供暖时，需要供暖的房间数减少1间。' },
